source:
@shader #threshold_palette {
  @uniform level: float(0,1,.5);
  @fn palette(t: float(0,1)): color(select(t,.5,#203040,#FFEEDD));
  @let strength: float(select(level,.5,.25,.75));
  @fragment { color: mix(#000000,palette(level),strength); }
}

